		/** 
		 * Tests creating a new Forecast.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Forecast");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Forecast" );

			try {            
				Forecast entity = ForecastService.getForecastInstance().createForecast( generateNewEntity() );
				thePrimaryKey = entity.getForecastId();
				LOGGER.info( "-- Successfully created a Forecast with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Forecast. 
		 */
		public Forecast testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Forecast" );

			Forecast entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Forecast with primary key" );
			msg.append( thePrimaryKey );
			
			ForecastFetchOneSummary fetchOneSummary = new ForecastFetchOneSummary( thePrimaryKey );

			try {
				entity = ForecastService.getForecastInstance().getForecast( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Forecast " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Forecast.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Forecast." );

			StringBuilder msg = new StringBuilder( "Failed to update a Forecast : " );        
			Forecast entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Forecast." );

				// for use later on...
				thePrimaryKey = entity.getForecastId();

				ForecastService proxy = ForecastService.getForecastInstance();            
				proxy.updateForecast( entity );   

				LOGGER.info( "-- Successfully saved Forecast - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Forecast.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Forecast." );

			try{
			    Forecast entity = testRead(); 
				ForecastService.getForecastInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Forecast with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Forecast with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Forecasts.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Forecasts:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Forecast : " );        
			List<Forecast> collection  = null;

			try {
				// call the static get method on the ForecastService
				collection = ForecastService.getForecastInstance().getAllForecast();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Forecast entity = null;            
					Iterator<Forecast> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getForecastId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

